export function getQuickToolbarPopupBounds(): DOMRect {
    const workspace = document.getElementById('ecom-workspace-wrapper');
    if (workspace) {
        return workspace.getBoundingClientRect();
    }
    return new DOMRect(0, 0, window.innerWidth, window.innerHeight);
}

export function getQuickToolbarTriggerElement(triggerRef: unknown): HTMLElement | null {
    if (!triggerRef) {
        return null;
    }
    const raw = Array.isArray(triggerRef) ? triggerRef[0] : triggerRef;
    if (raw instanceof HTMLElement) {
        return raw;
    }
    const el = (raw as { $el?: HTMLElement })?.$el;
    return el instanceof HTMLElement ? el : null;
}

export function positionQuickToolbarPopup(
    triggerEl: HTMLElement,
    popupEl: HTMLElement,
    options?: { gap?: number; padding?: number }
): void {
    const gap = options?.gap ?? 12;
    const padding = options?.padding ?? 8;
    const bounds = getQuickToolbarPopupBounds();

    popupEl.style.position = 'fixed';
    popupEl.style.transform = 'none';
    popupEl.style.margin = '0';
    popupEl.style.right = 'auto';
    popupEl.style.bottom = 'auto';

    const triggerRect = triggerEl.getBoundingClientRect();
    const popupWidth = popupEl.offsetWidth || popupEl.getBoundingClientRect().width;
    const popupHeight = popupEl.offsetHeight || popupEl.getBoundingClientRect().height;

    let top = triggerRect.bottom + gap;
    let left = triggerRect.left + (triggerRect.width - popupWidth) / 2;

    const minLeft = bounds.left + padding;
    const maxLeft = bounds.right - popupWidth - padding;
    if (popupWidth > 0) {
        left = Math.max(minLeft, Math.min(left, maxLeft));
    } else {
        left = Math.max(minLeft, Math.min(triggerRect.left, maxLeft));
    }

    const maxBottom = bounds.bottom - padding;
    const minTop = bounds.top + padding;

    if (popupHeight > 0 && top + popupHeight > maxBottom) {
        const above = triggerRect.top - popupHeight - gap;
        top = above >= minTop ? above : Math.max(minTop, maxBottom - popupHeight);
    } else if (top > maxBottom) {
        top = Math.max(minTop, maxBottom - (popupHeight || 120));
    }

    popupEl.style.top = `${Math.round(top)}px`;
    popupEl.style.left = `${Math.round(left)}px`;
}
