                'box_shadow': { icon: this.icons.borderRadius, isIcon: false },
                
                // Element Specific
                'gridTemplateColumns': { icon: this.icons.LayoutPopupIcon, isIcon: true },
                'zoom': { icon: this.icons.SearchMajor, isIcon: true },
                'gmap_height': { icon: this.icons.sizePopup, isIcon: true },
                'size': { icon: this.icons.sizePopup, isIcon: true },
                'imageHeight': { icon: this.icons.sizePopup, isIcon: true },
                'slider_config': { icon: this.icons.settings_icon, isIcon: true },
                'slider_effect': { icon: this.icons.ReplaceMajor, isIcon: true },

                // Table-specific
                'rows': { icon: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18M3 15h18"/></svg>', isIcon: false },
                'columns': { icon: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M9 3v18M15 3v18"/></svg>', isIcon: false },
                'background-color': { icon: this.icons.PaintBrushMajor, isIcon: true },
                'justify-content': { icon: this.icons.alignmentIcon, isIcon: false },
            };
            
            // Name matching has higher priority for specialized popup/dropdown types
            // Note: 'color' and 'background' types render inline natively, don't add button for them
            if (nameMap[name] && ['popup', 'dropdown', 'number'].includes(type)) {
                return nameMap[name];
            }

            const map = {
                'link':      { icon: this.icons.insertLink, isIcon: true },
                'dimension': { icon: this.icons.borderRadius, isIcon: false },
                'choose':    { icon: this.icons.alignmentIcon, isIcon: false },
                'popup':     { icon: this.icons.EditMajor, isIcon: true },
                'number':    { icon: this.icons.EditMajor, isIcon: true }
            };
            // Background type renders inline natively — no icon button needed
            // Color type is handled by colorquicktool — patchedField already remapped it, but
            // fallback guard in case field.type was already 'colorquicktool'
            if (['background', 'colorquicktool'].includes(type)) return null;
            // Original 'color' type (when NOT in Quick Toolbar) also renders inline natively
            if (type === 'color' && !this.isQuickToolBar) return null;

            return nameMap[name] || map[type] || null;
        },
        /** CSS classes for the popup-container wrapper */
        containerClasses() {
            return [{
                'flex justify-between': this.isOneLine,
                'flex-row-reverse': this.isReverse,
                'flex flex-col justify-start': this.field?.type === 'choose' && !this.isChooseOne,
            }];
        },
        isChooseOne() {
            return this.field?.options?.chooseOne;
        },
        refresh() {
            return this.$store.getters.REFRESH;
        },
        values() {
            return this.fieldValues;
        },
        field() {
            return this.data;
        },
        getCanResets() {
            return this.canResets;
        },
        canReset() {
            return (this.field?.options?.reset ?? false) === true ||
                (
                    ['number', 'dimension'].indexOf(this.field?.type) > -1 &&
                    this.field?.options?.reset !== false
                ) ||
                (
                    this.field?.type == 'picker' &&
                    this.field?.options?.type == 'icon' &&
                    this.field?.options?.reset !== false
                ) ||
                (this.field?.type === 'choose' &&
                    !this.isChooseOne &&
                    this.field?.options?.reset !== false)
                ;
        },
        isAIChangeable() {
            let post_id = this.$store.getters['page/params']?.post_id ?? null;
            if (!post_id) {
                return false;
            }
            return ['text', 'textarea', 'link', 'picker'].includes(this.field?.type) &&
                !['css', 'js', 'id', 'classes', 'custom-css', 'attributes'].includes(this.field.name) &&
                ['admin', 'manager', 'designer', 'supporter'].includes(this.$store.getters['global/user']?.roleName ?? '');
        },
        ctrfields() {
            return ['choose', 'toggle', 'popup', 'color', 'background', 'icon'];
        },
        isOneLine() {
            return this.field?.options?.oneline || this.ctrfields.indexOf(this.field.type) > -1 || this.field.options?.type === 'icon';
        },
        isReverse() {
            return this.isOneLine &&
                (this.ispop !== true || this.ctrfields.indexOf(this.field.type) > -1 || (this.field.type === 'picker' && !this.field.options?.multiple && this.field.options?.type === 'icon')) &&
                (this.field?.type == 'choose' && !this.field?.options?.chooseOne ? false : true);
        },
        isQtbToggleActive() {
            if (!this.isQuickToolBar || !['toggle', 'switch'].includes(this.patchedField?.type)) {
                return false;
            }
            const value = this.getData(this.group, this.patchedField);
            const onValue = this.patchedField?.options?.values?.on?.value;
            if (onValue !== undefined) {
                return value === onValue;
            }
            return !!value;
        },
        currentScreen() {
            return this.$store.getters['builder/currentScreen'];
        },
        ...mapGetters('builder', ['editingElement']),
        ...mapGetters('settings', ['globalData']),
        ...mapGetters('settings', ['isLiteMode']),

        fieldTitle() {
            if (this.field?.group_title) {
                return this.field?.label;
            }
            return this.field?.label;
        }
    },
    methods: {
        emitQtbCloseAllPopups(exceptUid = null) {
            if (!this.isQuickToolBar) {
                return;
            }
            this.$store.commit('builder/setIsPopupOpen', false);
            eventBus.emit(QTB_CLOSE_ALL_POPUPS, { exceptUid });
        },
        onQtbCloseAllPopups(payload) {
            if (payload?.exceptUid === this._uid) {
                return;
            }
            this.forceCloseQtbPopup();
        },
        forceCloseQtbPopup() {
            if (this.handleModalOpen) {
                this.closeModalQuickToolBar();
            }
            this.closeQtbFieldPopup();
        },
        closeQtbFieldPopup() {
            const refName = (this.patchedField?.type || this.field?.type) + 'Field';
            const comp = this.$refs[refName];
            const instance = Array.isArray(comp) ? comp[0] : comp;
            if (!instance) {
                return;
            }
            if (typeof instance.closeShowPopup === 'function') {
                instance.closeShowPopup();
                return;
            }
            if (instance.isopen) {
                if (typeof instance.doClose === 'function') {
                    instance.doClose();
                } else {
                    instance.isopen = false;
                }
            }
            if (typeof instance.close === 'function') {
                instance.close();
            }
        },
        onQtbPopupBeforeOpen() {
            if (!this.isQuickToolBar) {
                return;
            }
            this.emitQtbCloseAllPopups();
        },
        toggleQtbFieldValue() {
            const field = this.patchedField;
            const current = this.getData(this.group, field);
            const onValue = field?.options?.values?.on?.value;
            const offValue = field?.options?.values?.off?.value;
            if (onValue !== undefined && offValue !== undefined) {
                this.updateData(this.group, field, current === onValue ? offValue : onValue);
                return;
            }
            this.updateData(this.group, field, !current);
        },
        openModalQuickToolBar(event) {
            const type = this.patchedField?.type;

            if (type === 'toggle' || type === 'switch') {
                this.emitQtbCloseAllPopups();
                this.toggleQtbFieldValue();
                return;
            }

            if (type === 'picker') {
                const pickerType = this.patchedField.options?.type;
                let internalRefName = pickerType === 'image' || pickerType === 'icon' ? type + 'Field' : null;
                if (internalRefName) {
                    const comp = this.$refs[internalRefName];
                    const instance = Array.isArray(comp) ? comp[0] : comp;
                    if (instance && typeof instance.changeShowPopup === 'function') {
                        this.emitQtbCloseAllPopups({ exceptUid: this._uid });
                        instance.changeShowPopup();
                        if (pickerType === 'icon') {
                            this.handleModalOpen = true;
                            this.addEventListeners();
                            this.$nextTick(() => {
                                this.adjustPopupPosition();
                                this.scheduleQtbPopupReposition();
                            });
                        }
                        return;
                    }
                }
            }

            if (type === 'popup') {
                return;
            }

            if (this.handleModalOpen) {
                this.closeModalQuickToolBar();
                return;
            }

            this.emitQtbCloseAllPopups({ exceptUid: this._uid });
            this.handleModalOpen = true;
            this.addEventListeners();
            this.$nextTick(() => {
                this.adjustPopupPosition();
                this.scheduleQtbPopupReposition();
            });
        },
        closeQtbPickerModal() {
            this.closeQtbFieldPopup();
            this.onQtbIconPickerClosed();
        },
        onQtbIconPickerClosed() {
            if (this.patchedField?.options?.type !== 'icon') {
                return;
            }
            if (this.handleModalOpen) {
                this.handleModalOpen = false;
                this.cleanupEventListeners();
            }
        },
        getQtbTriggerElement() {
            return getQuickToolbarTriggerElement(this.$refs['modalButton' + this.field.type]);
        },
        getQtbPopupElement() {
            if (this.isQuickToolBar && this.patchedField?.type === 'picker' && this.patchedField?.options?.type === 'icon') {
                const anchored = document.querySelector('.ecom-picker-qtb-anchor');
                if (anchored) {
                    return anchored;
                }
            }
            const ref = this.$refs.popupHandler;
            const raw = Array.isArray(ref) ? ref[0] : ref;
            if (raw instanceof HTMLElement) {
                return raw;
            }
            if (raw?.$el instanceof HTMLElement) {
                return raw.$el;
            }
            return this.$el?.querySelector('.custom-quick-toolbar-fieldpopup-container')
                || this.$el?.querySelector('.barDimension');
        },
        adjustPopupPosition() {
            if (!this.isQuickToolBar || !this.handleModalOpen) {
                return;
            }
            const triggerEl = this.getQtbTriggerElement();
            const popupEl = this.getQtbPopupElement();
            if (triggerEl && popupEl) {
                positionQuickToolbarPopup(triggerEl, popupEl);
            }
        },
        scheduleQtbPopupReposition() {
            if (this.qtbPopupRepositionFrame) {
                cancelAnimationFrame(this.qtbPopupRepositionFrame);
            }
            this.qtbPopupRepositionFrame = requestAnimationFrame(() => {
                this.qtbPopupRepositionFrame = null;
                this.adjustPopupPosition();
            });
        },
        onQtbPopupLayoutChange() {
            this.scheduleQtbPopupReposition();
        },
        addEventListeners() {
            const idoc = window.EComposerBuilder?.contentDocument || document;
            if (idoc) {
                idoc.addEventListener('click', this.handleClickOutside);
            }
            document.addEventListener('click', this.handleClickOutside);
            window.addEventListener('resize', this.onQtbPopupLayoutChange);
            const workspace = document.getElementById('ecom-workspace-wrapper');
            if (workspace) {
                workspace.addEventListener('scroll', this.onQtbPopupLayoutChange, { passive: true });
            }
        },
        cleanupEventListeners() {
            const idoc = window.EComposerBuilder?.contentDocument || document;
            if (idoc) {
                idoc.removeEventListener('click', this.handleClickOutside);
            }
            document.removeEventListener('click', this.handleClickOutside);
            window.removeEventListener('resize', this.onQtbPopupLayoutChange);
            const workspace = document.getElementById('ecom-workspace-wrapper');
            if (workspace) {
                workspace.removeEventListener('scroll', this.onQtbPopupLayoutChange);
            }
            if (this.qtbPopupRepositionFrame) {
                cancelAnimationFrame(this.qtbPopupRepositionFrame);
                this.qtbPopupRepositionFrame = null;
            }
        },
        handleClickOutside(event) {
            if (this.handleModalOpen) {
                const refName = 'modalButton' + this.field.type;
                const modalButtonEl = this.$refs[refName];
                const refContentModal = this.field.type + 'Field';
                const subModalEl = this.$refs[refContentModal];
                const popupHandler = this.$refs['popupHandler'];

                // Sử dụng composedPath để kiểm tra toàn bộ path của event
                const popupEl = this.getQtbPopupElement();
                const isClickInPopup = event.composedPath().some((element) => {
                    if (element === popupHandler || element === popupEl) {
                        return true;
                    }
                    return element?.classList?.contains('custom-quick-toolbar-fieldpopup-container')
                        || element?.classList?.contains('quick-toolbar-field-popup')
                        || element?.classList?.contains('ecom-picker-qtb-anchor');
                });

                const modalButton = Array.isArray(modalButtonEl) ? modalButtonEl[0] : modalButtonEl;
                const modalButtonNode = modalButton?.$el ?? modalButton;
                const subModalNode = subModalEl?.$el ?? subModalEl;
                const isClickOnTrigger = modalButtonNode instanceof HTMLElement && modalButtonNode.contains(event.target);
                const isClickOnHiddenField = subModalNode instanceof HTMLElement && subModalNode.contains(event.target);

                if (modalButtonEl && !isClickOnTrigger && !isClickOnHiddenField && !isClickInPopup) {
                    if (this.patchedField?.type === 'picker' && this.patchedField?.options?.type === 'icon') {
                        this.closeQtbPickerModal();
                    } else {
                        this.closeModalQuickToolBar();
                    }
                }
            }
        },
        closeModalQuickToolBar() {
            this.handleModalOpen = false;
            this.$nextTick(() => {
                this.cleanupEventListeners();
            });
        },
        doOpenPopup() {
            if (this.$refs['popupField']) {
                this.$refs['popupField'].open();
            }
        },

        changeLabel(e) {
            this.$emit('update:label', [e.target.dataset.name, e.target.innerText])
        },
        valueGlobal(values, field) {
            let k;
            let v;
            delete field?.options?.global?.value;
            for (k in values) {
                if (k.startsWith('global-')) {
                    let value = values[k];
                    let type = /^global-([\w]+)/g.exec(k)?.[1];
                    let globalValue = this.globalData(type)?.[value]?.value;
                    if (globalValue) {
                        if (typeof globalValue === 'object') {
                            v = globalValue;
                        } else if (typeof globalValue === 'string') {
                            v = globalValue;
                        }
                        field.options.global.value = value;
                    }
                }
            }
            return v ?? values;
        },
        descs(g, f) {
            let descs = f.description;
            let rs = [];
            if (descs) {
                if (typeof descs === 'object') {
                    let p = this.pathField(g, f, false),
                        v = this.$helpers.valueByKey(p, this.values, '||');
                    if (descs.constructor === Object) {
                        descs = [descs];
                    }
                    descs.forEach(wn => {
                        let { content, condition } = wn;
                        if (content) {
                            if (!condition || condition(v, this.values)) {
                                rs.push(content);
                            }
                        }
                    });
                }
                else if (typeof descs === 'string') {
                    rs.push(descs);
                }
            }
            return rs;
        },
        checkDataEmpty(group, field) {
            function isEmpty(obj) {
                for (let key in obj) {
                    //if the value is 'object'
                    if (obj[key] instanceof Object === true) {
                        if (isEmpty(obj[key]) === false) return false;
                    }
                    //if value is string/number
                    else {
                        //if array or string have length is not 0.
                        if (obj[key].length !== 0) return false;
                    }
                }
                return true;
            }
            let name = this.fieldName(field);
            let v = group?.group_name ?
                this.values?.[group.group_name]?.[name] :
                this.values?.[name];
            const data = this.valueGlobal(v, field);
            if (typeof data === 'string' && data !== '' || typeof data === 'number') {
                return false;
            }

            if (data && typeof data === 'object') {
                return isEmpty(data);
            }

            return true;
        },
        getData(group, field) {
            let name = this.fieldName(field);
            let v = group?.group_name ?
                this.values?.[group.group_name]?.[name] :
                this.values?.[name];
            return this.valueGlobal(v, field);
        },
        getResponsiveData(group, field) {
            let name = this.fieldName(field);
            let value_desktop = {};
            let v = group?.group_name ?
                this.values?.[group.group_name]?.[name] :
                this.values?.[name];
            if (name.includes('__tablet') || name.includes('__mobile')) {
                let name_desktop = name.replace('__tablet', '').replace('__mobile', '');

                value_desktop = group?.group_name ? this.values?.[group.group_name]?.[name_desktop] : this.values?.[name_desktop];
                return v ? mergeDeep(this.$helpers.copy(value_desktop), this.$helpers.copy(v)) : this.$helpers.copy(value_desktop);
            }

            return v;

            function isObject(item) {
                return (item && typeof item === 'object' && !Array.isArray(item));
            }

            function mergeDeep(target, ...sources) {
                if (!sources.length) return target;
                const source = sources.shift();

                if (isObject(target) && isObject(source)) {
                    for (const key in source) {
                        if (isObject(source[key])) {
                            if (!target[key]) Object.assign(target, { [key]: {} });
                            mergeDeep(target[key], source[key]);
                        } else {
                            Object.assign(target, { [key]: source[key] });
                        }
                    }
                }

                return mergeDeep(target, ...sources);
            }

        },

        deleteObj(group, fieldName) {
            let values = {};
            if (group.group_name) {
                values = this.values[group.group_name]?.data;
                if (values) {
                    delete values[fieldName];
                    if (Object.keys(values).length === 0) {
                        delete this.values[group.group_name];
                    }
                }
            } else {
                values = this.values;
                delete values?.[fieldName];
            }
        },
        isValidValue(value) {
            return !(value == '__delete__' ||
                value == '__empty__' ||
                value === '' ||
                (!(value instanceof File) && typeof value === 'object' && Object.keys(value).length === 0)
            );
        },
        updateData(group, field, value) {
            let { group_name } = group;
            let field_name = this.fieldName(field);
            if (!field_name) {
                return;
            }
            let values = null;
            if (group_name) {
                this.values[group_name] = this.values[group_name] ?? {};
                values = this.values[group_name];
            }
            else {
                values = this.values;
            }
            if (this.isValidValue(value)) {
                values[field_name] = value;
            }
            else {
                delete values?.[field_name];
            }
            this.$emit('update:data', field, values);

        },
        deleteItem(field) {
            if (field.options?.delete !== false) {
                this.$emit('update:delete', field.name);
            }
        },
        valuePopup(group, field) {
            if (field.type === 'popup' && field.options?.type === 'dropdown') {
                let { preview = 'title' } = field.options;
                let optionsValues = field.options?.values;

                let values = {};

                if (typeof optionsValues === 'string') {
                    values = valuesDropdown[optionsValues] ?? [];
                }
                else if (typeof optionsValues === 'object') {
                    values = optionsValues;
                }
                let value = this.getData(group, field);

                if (value === undefined) {
                    return this.$t('default');
                }
                let isArrValues = values.constructor === Array;
                value = isArrValues ?
                    values.filter(it => it.name === value)[0] :
                    value;
                let rs;

                if (preview === 'value') {
                    rs = value?.name ?? value;
                }
                else {
                    rs = isArrValues ? value?.title : values[value];
                }
                return typeof rs === 'string' ? rs.replace(/_/g, ' ') : rs;
            }
        }
    }
};
</script>
